 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Locate the three-cell line that forms the given pattern.
    pattern = None
    for r in range(h):
        for c in range(w):
            if c + 2 < w and all(grid[r][c+i] != bg for i in range(3)):
                pattern = [(0, i, grid[r][c+i]) for i in range(3)]
                anchor = (0, 1)
                break
            if r + 2 < h and all(grid[r+i][c] != bg for i in range(3)):
                pattern = [(i, 0, grid[r+i][c]) for i in range(3)]
                anchor = (1, 0)
                break
        if pattern:
            break
    if pattern is None:
        return [row[:] for row in grid]
    # All other non-background cells are markers; place a copy centered on each.
    pat_cells = set()
    for dr, dc, _ in pattern:
        pat_cells.add((r + dr, c + dc))
    out = [row[:] for row in grid]
    markers = [(rr, cc) for rr in range(h) for cc in range(w)
               if grid[rr][cc] != bg and (rr, cc) not in pat_cells]
    for rr, cc in markers:
        for dr, dc, val in pattern:
            y, x = rr + dr - anchor[0], cc + dc - anchor[1]
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = val
    return out
